/** Generated by scaffold-crud-pages. Query hooks for AuditLogs.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchAuditLogsList,
  fetchAuditLogsById,
  createAuditLogs,
  updateAuditLogs,
  deleteAuditLogs,
  type FetchAuditLogsListParams,
} from '~/services/httpServices/auditLogsService';
import type { CreateAuditLogsRequest, UpdateAuditLogsRequest } from '~/types/audit-logs';

const DOMAIN = 'auditLogs';

export function useAuditLogsList(params?: FetchAuditLogsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchAuditLogsList(params),
  });
}

export function useAuditLogs(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchAuditLogsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateAuditLogs() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateAuditLogsRequest) => createAuditLogs(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateAuditLogs() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateAuditLogsRequest }) =>
      updateAuditLogs(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteAuditLogs() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteAuditLogs(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
